CREATE OR REPLACE FUNCTION public.preserve_catalog_creation_time() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $fn$ BEGIN IF TG_OP='INSERT' THEN NEW.created_at:=now(); ELSE NEW.created_at:=OLD.created_at; END IF; RETURN NEW; END $fn$; CREATE TRIGGER preserve_catalog_creation_time BEFORE INSERT OR UPDATE ON public.marketplace_content FOR EACH ROW EXECUTE FUNCTION public.preserve_catalog_creation_time();